<?php
namespace App\Commands\AiOps; use App\Commands\SafeBaseCommand; use App\Commands\Support\SubsCommandTrait;
class SelfHeal extends SafeBaseCommand { use SubsCommandTrait; protected $group='AiOps'; protected $name='aiops:self-heal'; protected $description='Run one-pass self-heal'; protected $options=['--attempts'=>'max 3','--json'=>'JSON']; public function run(array $params){$this->parseParams($params);$json=$this->optBool('json');$attempts=max(1,min(3,$this->optInt('attempts', 1)));$lock=ROOTPATH.'aiops/runtime/selfheal.lock'; if(is_file($lock) && (time()-filemtime($lock))<600){$out=['status'=>'locked','message'=>'self-heal already running'];$this->emit($out,$json);return EXIT_SUCCESS;} file_put_contents($lock,(string)getmypid()); try {$runs=[]; for($i=1;$i<=$attempts;$i++){ $audit=command('aiops:audit --json=1'); $repair=command('aiops:repair --json=1'); $status=command('aiops:status --json=1'); $runs[]=['cycle'=>$i,'audit'=>$audit,'repair'=>$repair,'status'=>$status]; } $md="# Self Heal ".date('c')."\n\nAttempts: {$attempts}\n"; $path=$this->writeDoc('nightly','self-heal-'.date('Y-m-d--Hi').'.md',$md); $out=['status'=>'ok','attempts'=>$attempts,'report'=>$path]; } finally {@unlink($lock);} $this->emit($out,$json); return EXIT_SUCCESS; }}
